query P34($owner: String!, $name: String!, $issue: Int!) {
  repository(owner: $owner, name: $name) {
    nameWithOwner
    issue(number: $issue) {
      number state stateReason title createdAt updatedAt lastEditedAt closedAt
      author { login __typename }
      authorAssociation
      editor { login __typename }
      userContentEdits(first: 10) {
        totalCount
        nodes { editor { login __typename } editedAt createdAt updatedAt deletedAt }
      }
      timelineItems(itemTypes: [RENAMED_TITLE_EVENT, REOPENED_EVENT, CLOSED_EVENT, LABELED_EVENT, ISSUE_COMMENT], first: 50) {
        totalCount
        nodes {
          __typename
          ... on RenamedTitleEvent { actor { login __typename } createdAt previousTitle currentTitle }
          ... on ReopenedEvent { actor { login __typename } createdAt }
          ... on ClosedEvent { actor { login __typename } createdAt stateReason }
          ... on LabeledEvent { actor { login __typename } createdAt label { name } }
          ... on IssueComment { author { login __typename } createdAt }
        }
      }
    }
  }
}
